function parseDuration(value: string): number | undefined;
function parseDuration(value: number): string;
function parseDuration(value: string | number): number | string | undefined {
  if (typeof value === "number") {
    const minutes = value / 60_000;
    return minutes % 60 === 0 ? `${minutes / 60}h` : `${minutes}m`;
  }
  const match = /^(\d+)(h|m)$/.exec(value);
  if (!match) return undefined;
  return Number(match[1]) * (match[2] === "h" ? 3_600_000 : 60_000);
}

console.log(parseDuration("2h"), parseDuration("30m"), parseDuration("soon"));
console.log(parseDuration(7_200_000), parseDuration(5_400_000));

