type NodeEnv = "development" | "production" | "test";
const NODE_ENVS: readonly NodeEnv[] = ["development", "production", "test"];

function readEnv(env: Record<string, string | undefined>): { nodeEnv: NodeEnv; paystackKey: string } {
  const problems: string[] = [];
  const rawEnv = env.NODE_ENV ?? "development";
  const nodeEnv = NODE_ENVS.find((value) => value === rawEnv);
  if (!nodeEnv) problems.push(`NODE_ENV must be one of ${NODE_ENVS.join(", ")}`);
  const paystackKey = env.PAYSTACK_SECRET_KEY;
  if (!paystackKey?.startsWith("sk_")) problems.push("PAYSTACK_SECRET_KEY must start with sk_");
  if (!nodeEnv || !paystackKey || problems.length > 0) throw new Error(problems.join("; "));
  return { nodeEnv, paystackKey };
}

console.log(readEnv({ NODE_ENV: "production", PAYSTACK_SECRET_KEY: "sk_live_123" }));
try {
  console.log(readEnv({ NODE_ENV: "staging" }));
} catch (error) {
  console.log((error as Error).message);
}

