interface Cart {
  id: string;
  items: { kobo: number; quantity: number }[];
}

interface Cart {
  coupon?: { code: string; percentOff: number };
}

function total(cart: Cart): number {
  const gross = cart.items.reduce((sum, item) => sum + item.kobo * item.quantity, 0);
  return cart.coupon ? Math.round(gross * (1 - cart.coupon.percentOff / 100)) : gross;
}

const cart: Cart = { id: "C-1", items: [{ kobo: 333_333, quantity: 3 }] };
console.log(total(cart));
console.log(total({ ...cart, coupon: { code: "SALLAH10", percentOff: 10 } }));

