const untyped: any = {
  format(kobo: any) {
    return `₦${(kobo / 100).toFixed(2)}`;
  },
};

function formatKobo(kobo: number): string {
  if (!Number.isSafeInteger(kobo)) throw new TypeError("kobo must be a whole number");
  const text: unknown = untyped.format(kobo);
  if (typeof text !== "string") throw new TypeError("formatter returned a non-string");
  return text;
}

for (const value of [250_000, 2500.5, Number("2,500")]) {
  try {
    console.log(formatKobo(value));
  } catch (error) {
    console.log(`${(error as Error).name}: ${(error as Error).message}`);
  }
}

