function formatKobo(kobo: number): string {
  const naira = Math.floor(kobo / 100);
  const rest = String(kobo % 100).padStart(2, "0");
  return `₦${naira.toLocaleString("en-US")}.${rest}`;
}

function parseKobo(text: string): number | null {
  const cleaned = text.replace(/[₦,\s]/g, "");
  if (!/^\d+(\.\d{1,2})?$/.test(cleaned)) return null;
  return Math.round(Number(cleaned) * 100);
}

function priceLabel(fromForm: string): string {
  const kobo = parseKobo(fromForm);
  if (kobo === null) return `Invalid amount: "${fromForm}"`;
  return `Total: ${formatKobo(kobo)}`;
}

for (const input of ["2500", "₦1,250.50", "two thousand", "-5"]) console.log(priceLabel(input));

