type Charge = { reference: string; kobo: number; status: "success" | "failed" };

function isCharge(value: unknown): value is Charge {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.reference === "string" &&
    typeof v.kobo === "number" &&
    Number.isSafeInteger(v.kobo) &&
    (v.status === "success" || v.status === "failed")
  );
}

const replies: unknown[] = [
  { reference: "PSK_1", kobo: 250_000, status: "success" },
  { reference: "PSK_2", kobo: "250000", status: "success" },
  { reference: "PSK_3", kobo: 99_000, status: "pending" },
  null,
];
for (const reply of replies) console.log(isCharge(reply) ? `ok ${reply.reference}` : "rejected");
